"""Check Google Meet attendance for active meetings via GWS CLI.

Determines whether the user has joined a Google Meet conference associated
with a calendar event. Used to suppress missed-meeting alerts for meetings
the user attended (even if they left early).

The Meet API conference record gets an endTime as soon as the last participant
leaves or the organizer ends the call — this can happen well before the
calendar event's end time. So we check ALL conference records for the meeting
code (not just active ones) to detect prior attendance.
"""

from __future__ import annotations

import json
import logging
import re
from urllib.parse import urlparse

from personal_assistant_dashboard.config import GWS_BINARY
from personal_assistant_dashboard.models import CalendarEvent
from personal_assistant_dashboard.utils import run_cmd

logger = logging.getLogger(__name__)

# Meet URL pattern: https://meet.google.com/abc-defg-hij
_MEET_CODE_RE = re.compile(r"[a-z]{3}-[a-z]{4}-[a-z]{3}")

# Cached user ID (people/me resource ID) — doesn't change within a session
_cached_user_id: str | None = None


def _extract_meeting_code(hangout_link: str) -> str | None:
    """Extract meeting code from a Google Meet URL."""
    try:
        path = urlparse(hangout_link).path.lstrip("/")
    except Exception:
        return None
    match = _MEET_CODE_RE.search(path)
    return match.group(0) if match else None


def _get_user_resource_id() -> str | None:
    """Get the authenticated user's resource ID via People API.

    Returns the numeric ID from people/me metadata (e.g., '103844...').
    The Meet API uses 'users/<id>' format for signedinUser.user.
    """
    global _cached_user_id
    if _cached_user_id is not None:
        return _cached_user_id

    try:
        result = run_cmd(
            [
                GWS_BINARY,
                "people",
                "people",
                "get",
                "--params",
                json.dumps(
                    {
                        "resourceName": "people/me",
                        "personFields": "metadata",
                    }
                ),
                "--format",
                "json",
            ],
            timeout=15,
        )
    except (FileNotFoundError, Exception):
        return None
    if result.returncode != 0:
        return None
    try:
        data = json.loads(result.stdout)
        resource_name = data.get("resourceName", "")
        if resource_name.startswith("people/"):
            _cached_user_id = resource_name.split("/", 1)[1]
            return _cached_user_id
    except (json.JSONDecodeError, KeyError):
        pass
    return None


def _find_conference_names(meeting_code: str) -> list[str]:
    """Find all conference record names for a meeting code.

    Returns all records (active and ended) so we can check attendance
    even after the Meet session has concluded.
    """
    try:
        result = run_cmd(
            [
                GWS_BINARY,
                "meet",
                "conferenceRecords",
                "list",
                "--params",
                json.dumps({"filter": f'space.meeting_code="{meeting_code}"'}),
                "--format",
                "json",
            ],
            timeout=15,
        )
    except (FileNotFoundError, Exception):
        logger.debug("Failed to query Meet API for code %s", meeting_code)
        return []
    if result.returncode != 0:
        logger.debug(
            "Meet API error for %s: %s",
            meeting_code,
            result.stderr[:80],
        )
        return []
    try:
        data = json.loads(result.stdout)
    except json.JSONDecodeError:
        return []
    return [r["name"] for r in data.get("conferenceRecords", []) if "name" in r]


def _user_in_conference(conference_name: str, user_id: str) -> bool:
    """Check if user has joined this conference at any point.

    Checks all participants (not just active ones) so that joining
    and leaving early does not re-trigger the missed meeting alert.
    """
    try:
        result = run_cmd(
            [
                GWS_BINARY,
                "meet",
                "conferenceRecords",
                "participants",
                "list",
                "--params",
                json.dumps(
                    {
                        "parent": conference_name,
                    }
                ),
                "--format",
                "json",
            ],
            timeout=15,
        )
    except (FileNotFoundError, Exception):
        return False
    if result.returncode != 0:
        return False
    try:
        data = json.loads(result.stdout)
    except json.JSONDecodeError:
        return False
    user_resource = f"users/{user_id}"
    for participant in data.get("participants", []):
        signed_in = participant.get("signedinUser", {})
        if signed_in.get("user") == user_resource:
            return True
    return False


def find_attended_event_ids(events: list[CalendarEvent]) -> set[str]:
    """Return event IDs for meetings the user has joined (or is still in).

    For each event with a Google Meet hangout_link, finds all conference
    records for that meeting code (active or ended) and checks whether the
    user was a participant in any of them. This means leaving a meeting
    early will NOT re-trigger the alert.
    """
    events_by_code: dict[str, list[CalendarEvent]] = {}
    for event in events:
        link = event.get("hangout_link")
        if not link:
            continue
        code = _extract_meeting_code(link)
        if code:
            events_by_code.setdefault(code, []).append(event)

    if not events_by_code:
        return set()

    user_id = _get_user_resource_id()
    if not user_id:
        logger.debug("Could not determine user ID for Meet attendance check")
        return set()

    attended_ids: set[str] = set()
    for code, code_events in events_by_code.items():
        conf_names = _find_conference_names(code)
        if not conf_names:
            continue
        for conf_name in conf_names:
            if _user_in_conference(conf_name, user_id):
                for evt in code_events:
                    event_id = evt.get("id", "")
                    if event_id:
                        attended_ids.add(event_id)
                        logger.debug(
                            "User attended meeting: %s",
                            evt.get("summary"),
                        )
                break  # Found attendance, no need to check older records

    return attended_ids
